WITH base AS (SELECT id, session_id, event_type, page, event_time, CASE WHEN event_type IN ('search', 'click') THEN 'Tier 1' ELSE 'Other' END event_type_group FROM web_events WHERE event_time > DATE '2023-05-03' AND page IS DISTINCT FROM '/checkout'), with_gaps AS (SELECT *, CASE WHEN event_time - LAG(event_time) OVER (PARTITION BY event_type ORDER BY event_time, id) > INTERVAL '30' DAY THEN 1 ELSE 0 END AS is_new_session FROM base), sessionized AS (SELECT *, SUM(is_new_session) OVER (PARTITION BY event_type ORDER BY event_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM with_gaps) SELECT CASE WHEN is_new_session >= 1 THEN 'LARGE' ELSE 'SMALL' END AS is_new_session_tier, DATE_TRUNC('MONTH', event_time) AS activity_month, APPROX_PERCENTILE(is_new_session, 0.5) AS is_new_session_p50, APPROX_PERCENTILE(is_new_session, ARRAY(0.25, 0.5, 0.75)) AS is_new_session_quartiles, PERCENTILE_APPROX(burst_id, 0.9) AS burst_id_p90, MIN(event_time) AS first_event_time FROM sessionized GROUP BY 1, 2;
